import{_ as t}from"./chunks/100.I7A0VXqr.js";import{_ as a,o,c as n,ak as r}from"./chunks/framework.DC-k2h36.js";const i="/projects/esp32Sensor/en/latest/assets/1.ur1crUo0.webp",s="/projects/esp32Sensor/en/latest/assets/2.BBqXDaCl.webp",l="/projects/esp32Sensor/en/latest/assets/3.BhtP7wiM.webp",c="/projects/esp32Sensor/en/latest/assets/4.DQf9ezyB.webp",v=JSON.parse('{"title":"7. Infrared Obstacle Avoidance Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"docs/7. Infrared Obstacle Avoidance Sensor.md","filePath":"docs/7. Infrared Obstacle Avoidance Sensor.md"}'),d={name:"docs/7. Infrared Obstacle Avoidance Sensor.md"};function h(p,e,m,g,u,b){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="_7-infrared-obstacle-avoidance-sensor" tabindex="-1">7. Infrared Obstacle Avoidance Sensor <a class="header-anchor" href="#_7-infrared-obstacle-avoidance-sensor" aria-label="Permalink to &quot;7. Infrared Obstacle Avoidance Sensor&quot;">​</a></h1><h2 id="_7-1-introduction" tabindex="-1">7.1 Introduction <a class="header-anchor" href="#_7-1-introduction" aria-label="Permalink to &quot;7.1 Introduction&quot;">​</a></h2><p>The infrared obstacle avoidance sensor detects the presence of obstacles in front of it. Equipped with an infrared emitter tube and an infrared receiver tube, the sensor projects infrared light that reflects off obstacles and enters the receiver tube. This sensor is widely used for obstacle avoidance in robots and smart vehicles.</p><img loading="lazy" height="1156" width="1156" src="'+i+'" class="common_img" style="width:300px;"><h2 id="_7-2-technical-specifications" tabindex="-1">7.2 Technical Specifications <a class="header-anchor" href="#_7-2-technical-specifications" aria-label="Permalink to &quot;7.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Adjustment method</td><td style="text-align:center;">Miniature potentiometer adjustment</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">39.5 × 23.4 × 12.2 mm</td></tr></tbody></table><h2 id="_7-3-adjustment-method" tabindex="-1">7.3 Adjustment Method <a class="header-anchor" href="#_7-3-adjustment-method" aria-label="Permalink to &quot;7.3 Adjustment Method&quot;">​</a></h2><p>Rotating the onboard miniature potentiometer adjusts the infrared detection range. Rotating clockwise increases the detection range, and rotating counterclockwise decreases the detection range.</p><h2 id="_7-4-hands-on-project" tabindex="-1">7.4 Hands-On Project <a class="header-anchor" href="#_7-4-hands-on-project" aria-label="Permalink to &quot;7.4 Hands-On Project&quot;">​</a></h2><h3 id="_7-4-1-project-overview" tabindex="-1">7.4.1 Project Overview <a class="header-anchor" href="#_7-4-1-project-overview" aria-label="Permalink to &quot;7.4.1 Project Overview&quot;">​</a></h3><p>This project uses the infrared obstacle avoidance sensor and onboard RGB LEDs to provide visual alerts for obstacle detection. When the infrared obstacle avoidance sensor detects an obstacle ahead, all RGB LEDs illuminate in red. When no obstacle is detected ahead, all RGB LEDs illuminate in green, demonstrating obstacle signal acquisition and conditional branch programming logic.</p><h3 id="_7-4-2-hardware-wiring" tabindex="-1">7.4.2 Hardware Wiring <a class="header-anchor" href="#_7-4-2-hardware-wiring" aria-label="Permalink to &quot;7.4.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the infrared obstacle avoidance sensor to port <strong>P5</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="623" src="'+s+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This sensor supports connection to any port among P5, P6, P7, or P8 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h3 id="_7-4-3-adding-extensions" tabindex="-1">7.4.3 Adding Extensions <a class="header-anchor" href="#_7-4-3-adding-extensions" aria-label="Permalink to &quot;7.4.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>IR obstacle avoidance sensor</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_7-4-4-complete-program-and-analysis" tabindex="-1">7.4.4 Complete Program and Analysis <a class="header-anchor" href="#_7-4-4-complete-program-and-analysis" aria-label="Permalink to &quot;7.4.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Inside the main program loop, the detection state of the infrared obstacle avoidance sensor on port P5 is continuously monitored to perform conditional judgment:</p><ul><li><p>When an obstacle is detected, all RGB LEDs illuminate in red.</p></li><li><p>When no obstacle is detected, all RGB LEDs illuminate in green.</p></li></ul></li><li><p>A 0.1 s delay is executed at the end of each loop iteration before repeating the entire obstacle detection routine.</p></li></ol><img loading="lazy" height="428" width="852" src="'+c+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">01 Program Files/07 Infrared Obstacle Avoidance Sensor.sb3</a>.</strong></p></div><h3 id="_7-4-5-program-upload" tabindex="-1">7.4.5 Program Upload <a class="header-anchor" href="#_7-4-5-program-upload" aria-label="Permalink to &quot;7.4.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+t+'" class="common_img" style="width:800px;"><h3 id="_7-4-6-program-outcome" tabindex="-1">7.4.6 Program Outcome <a class="header-anchor" href="#_7-4-6-program-outcome" aria-label="Permalink to &quot;7.4.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, the infrared obstacle avoidance sensor monitors obstacles in front of it continuously. When an object approaches the detection area of the sensor, the RGB LEDs illuminate in red. When the object is removed and the space in front of the sensor is clear, the RGB LEDs switch to green automatically, providing immediate visual feedback on obstacle detection.</p>',27)])])}const x=a(d,[["render",h]]);export{v as __pageData,x as default};
